// ─── Shared atoms ───
function StarField({ count=40, seed=1 }) {
  const stars = Array.from({length:count}, (_,i) => ({
    id:i, x:((i*37*seed+11)%97), y:((i*53*seed+7)%95),
    s:(i%3)+1, op:0.25+(i%5)*0.13, tw:i%4===0,
  }));
  return (
    <div style={{position:"absolute",inset:0,pointerEvents:"none",overflow:"hidden"}}>
      {stars.map(s => (
        <div key={s.id} style={{
          position:"absolute", left:`${s.x}%`, top:`${s.y}%`,
          width:s.s, height:s.s, borderRadius:"50%",
          background:s.tw?"#fffbe0":"white", opacity:s.op,
          boxShadow:s.tw?`0 0 ${s.s*2}px #fffbe0`:"none",
        }}/>
      ))}
    </div>
  );
}

function Btn({children,onClick,color=PURPLE,outlined=false,style={}}) {
  return (
    <button onClick={onClick} style={{
      background:outlined?"transparent":`linear-gradient(135deg,${color}ee,${color}99)`,
      border:`2px solid ${color}`, borderRadius:999, color:WHITE,
      fontWeight:800, fontSize:14, padding:"10px 26px", cursor:"pointer",
      boxShadow:outlined?"none":`0 4px 20px ${color}55`,
      letterSpacing:0.3, fontFamily:"inherit", ...style,
    }}>{children}</button>
  );
}

function ProgressBar({value,color}) {
  return (
    <div style={{width:"100%",height:8,background:"#ffffff18",borderRadius:99,overflow:"hidden"}}>
      <div style={{width:`${value}%`,height:"100%",background:`linear-gradient(90deg,${color},${color}88)`,borderRadius:99,transition:"width 0.4s"}}/>
    </div>
  );
}

function Badge({color,children}) {
  return <span style={{background:`${color}33`,border:`1px solid ${color}88`,borderRadius:20,padding:"3px 12px",fontSize:11,color:WHITE,fontWeight:700}}>{children}</span>;
}

// ─── Planet SVG (used in map) ───
function PlanetSVG({world,size,locked}) {
  const c=world.color, a=world.accent, s=size, id=world.id;
  return (
    <div style={{position:"relative",width:size,height:size}}>
      {/* Sprite image as planet surface */}
      <div style={{
        width:size, height:size, borderRadius:"50%", overflow:"hidden",
        background:`radial-gradient(circle at 35% 35%, ${a}dd, ${c}88)`,
        boxShadow:locked?`0 0 ${size*0.1}px #00000088`:`0 0 ${size*0.22}px ${c}cc, 0 0 ${size*0.1}px ${c}88`,
        filter:locked?"grayscale(0.8) brightness(0.45)":"none",
        position:"relative",
      }}>
        <img src={SPRITES[world.sprite]} alt={world.name}
          style={{width:"100%",height:"100%",objectFit:"cover",objectPosition:"center",mixBlendMode:"multiply"}}/>
        {/* Overlay for planet feel */}
        <div style={{position:"absolute",inset:0,borderRadius:"50%",
          background:`radial-gradient(circle at 30% 25%, ${a}44 0%, transparent 60%), radial-gradient(circle at 70% 75%, ${c}66 0%, transparent 50%)`
        }}/>
        {/* Shine */}
        <div style={{position:"absolute",top:"8%",left:"15%",width:"35%",height:"22%",borderRadius:"50%",
          background:"rgba(255,255,255,0.18)",transform:"rotate(-25deg)"}}/>
        {locked && <div style={{position:"absolute",inset:0,background:"rgba(0,0,0,0.5)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:size*0.25}}>🔒</div>}
      </div>
      {/* Ring for some worlds */}
      {(id==="jogos"||id==="maquiagem") && !locked && (
        <div style={{
          position:"absolute", top:"42%", left:"-18%", width:"136%", height:"18%",
          borderRadius:"50%", border:`${Math.max(2,size*0.04)}px solid ${a}77`,
          transform:"rotateX(72deg)", pointerEvents:"none", zIndex:2,
        }}/>
      )}
    </div>
  );
}

// ─── Rocket SVG ───
function RocketSVG({size=40, angle=0}) {
  return (
    <svg width={size} height={size} viewBox="0 0 60 60" style={{transform:`rotate(${angle}deg)`}}>
      <ellipse cx="30" cy="26" rx="10" ry="18" fill="#E0D4FF" fillOpacity="0.95"/>
      <ellipse cx="30" cy="10" rx="10" ry="12" fill={PURPLE_LIGHT} fillOpacity="0.9"/>
      <polygon points="20,38 12,50 22,44" fill={TEAL} opacity="0.9"/>
      <polygon points="40,38 48,50 38,44" fill={TEAL} opacity="0.9"/>
      <circle cx="30" cy="24" r="5" fill={BG} stroke={TEAL_LIGHT} strokeWidth="1.5"/>
      <circle cx="30" cy="24" r="2.5" fill={TEAL_LIGHT} fillOpacity="0.5"/>
      <ellipse cx="30" cy="48" rx="6" ry="9" fill="#FF6B2B" fillOpacity="0.8"/>
      <ellipse cx="30" cy="48" rx="3" ry="5" fill={STAR_Y} fillOpacity="0.9"/>
    </svg>
  );
}

