function Screen02_Mode({go}) {
  const [sel,setSel] = useState([0,1,2]);
  const toggle = i => setSel(s=>s.includes(i)?s.filter(x=>x!==i):[...s,i]);
  return (
    <div style={{position:"relative",minHeight:"100%",background:`radial-gradient(ellipse at 50% 10%, #1a0d4a, ${BG})`,padding:"28px 22px 32px",display:"flex",flexDirection:"column",gap:14}}>
      <StarField count={25} seed={2}/>
      <div style={{position:"relative",zIndex:1}}>
        <div style={{fontSize:22,fontWeight:900,color:WHITE}}>Modo Pai / Mãe 👨‍🚀</div>
        <div style={{fontSize:13,color:"#c4b5fd",lineHeight:1.6,marginTop:6,marginBottom:14}}>
          Aprenda as gírias que a Geração Z usa e entre na conversa!
        </div>
        <div style={{fontSize:12,color:PURPLE_LIGHT,fontWeight:700,marginBottom:10}}>Quais universos explorar?</div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:7}}>
          {WORLDS.map((w,i)=>(
            <div key={i} onClick={()=>toggle(i)} style={{display:"flex",alignItems:"center",gap:7,padding:"7px 10px",background:sel.includes(i)?`${w.color}33`:CARD2,border:`1.5px solid ${sel.includes(i)?w.color+"88":"#333"}`,borderRadius:10,cursor:"pointer",transition:"all 0.2s"}}>
              <div style={{width:16,height:16,borderRadius:4,background:sel.includes(i)?w.color:"#333",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                {sel.includes(i)&&<span style={{fontSize:10,color:"white"}}>✓</span>}
              </div>
              <span style={{fontSize:11,color:WHITE,fontWeight:600}}>{w.short}</span>
            </div>
          ))}
        </div>
        <div style={{marginTop:18}}><Btn onClick={()=>go("map")} color={PURPLE} style={{width:"100%"}}>Embarcar 🚀</Btn></div>
      </div>
    </div>
  );
}

