// ══════════════════════════════════════════
// SCREEN 5 — LIÇÃO / QUIZ MELHORADO
// ══════════════════════════════════════════
function Screen05_Lesson({go}) {
  const w = WORLDS[0];
  const quiz = getQuiz(w.id);
  const [step,setStep] = useState(0);
  const [phase,setPhase] = useState("explain"); // "explain" | "question" | "feedback"
  const [chosen,setChosen] = useState(null);
  const [score,setScore] = useState({acertos:0,erros:0});
  const q = quiz[step % quiz.length];
  const isCorrect = chosen === q.correta;

  const handleAnswer = (i) => {
    if(phase!=="question") return;
    setChosen(i);
    setPhase("feedback");
    setScore(s=>({acertos:s.acertos+(i===q.correta?1:0),erros:s.erros+(i===q.correta?0:1)}));
  };
  const handleNext = () => {
    setChosen(null);
    setPhase("explain");
    if(step+1>=quiz.length) go("review");
    else setStep(s=>s+1);
  };

  return (
    <div style={{position:"relative",minHeight:"100%",background:`linear-gradient(180deg, ${w.sky1} 0%, ${BG} 100%)`,padding:"18px 18px 24px",display:"flex",flexDirection:"column",gap:12}}>
      <StarField count={16} seed={5}/>
      <div style={{position:"relative",zIndex:1}}>
        {/* Header */}
        <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:12}}>
          <button onClick={()=>go("world_intro")} style={{background:"none",border:"none",color:PURPLE_LIGHT,fontSize:16,cursor:"pointer",padding:0,fontFamily:"inherit"}}>✕</button>
          <div style={{flex:1}}><ProgressBar value={((step)/quiz.length)*100+8} color={w.color}/></div>
          <div style={{display:"flex",gap:8,fontSize:12}}>
            <span style={{color:"#4ade80",fontWeight:700}}>✓ {score.acertos}</span>
            <span style={{color:"#f87171",fontWeight:700}}>✗ {score.erros}</span>
          </div>
        </div>

        {/* === PHASE: EXPLAIN === */}
        {phase==="explain" && (
          <div>
            <div style={{textAlign:"center",marginBottom:14}}>
              <div style={{fontSize:10,color:w.accent,fontWeight:700,letterSpacing:2,textTransform:"uppercase",marginBottom:4}}>
                {q.tipo==="complete"?"Complete a frase":"Identifique o significado"}
              </div>
              <div style={{fontSize:42,fontWeight:900,color:WHITE,letterSpacing:3,textShadow:`0 0 30px ${w.color}99`}}>{q.slang}</div>
              <div style={{fontSize:11,color:w.accent,fontWeight:600,marginTop:4}}>{q.classe}</div>
            </div>
            {/* Alien + explanation */}
            <div style={{display:"flex",gap:12,alignItems:"flex-end",marginBottom:12}}>
              <div style={{flexShrink:0,width:56,height:56,borderRadius:12,overflow:"hidden",background:`${w.color}22`,border:`1.5px solid ${w.color}66`}}>
                <img src={SPRITES.alien} alt="alien" style={{width:"100%",height:"100%",objectFit:"contain"}}/>
              </div>
              <div style={{background:`${w.color}22`,border:`1px solid ${w.color}66`,borderRadius:"14px 14px 14px 4px",padding:"10px 13px",fontSize:12,color:WHITE,lineHeight:1.6,flex:1}}>
                <strong>Significado:</strong> {q.significado}
              </div>
            </div>
            {/* Details card */}
            <div style={{background:CARD2,borderRadius:16,padding:"13px 15px",border:`1px solid ${w.color}33`,marginBottom:14}}>
              <div style={{fontSize:11,color:PURPLE_LIGHT,fontWeight:700,marginBottom:4}}>Exemplo de uso:</div>
              <div style={{fontSize:12,color:WHITE,fontStyle:"italic",lineHeight:1.55,marginBottom:8}}>{q.exemplo}</div>
              {/* Usage sentence highlight */}
              <div style={{background:`${w.color}18`,borderRadius:10,padding:"8px 11px"}}>
                <div style={{fontSize:10,color:w.accent,fontWeight:700,marginBottom:3}}>
                  {q.tipo==="complete"?"Complete a frase ↓":"Identifique o significado ↓"}
                </div>
                <div style={{fontSize:12,color:"#e0d4ff",lineHeight:1.5}}>{q.frase}</div>
              </div>
            </div>
            <Btn onClick={()=>setPhase("question")} color={w.color} style={{width:"100%"}}>
              Entendi! Fazer Pergunta →
            </Btn>
          </div>
        )}

        {/* === PHASE: QUESTION === */}
        {phase==="question" && (
          <div>
            <div style={{background:`${w.color}22`,border:`2px solid ${w.color}66`,borderRadius:16,padding:"14px 16px",marginBottom:14,textAlign:"center"}}>
              <div style={{fontSize:11,color:w.accent,fontWeight:700,letterSpacing:1.5,textTransform:"uppercase",marginBottom:6}}>
                {q.tipo==="complete"?"Complete a frase":"O que significa?"}
              </div>
              <div style={{fontSize:14,color:WHITE,lineHeight:1.6,fontWeight:500}}>{q.frase}</div>
            </div>
            {/* Alien asking */}
            <div style={{display:"flex",gap:10,alignItems:"flex-end",marginBottom:12}}>
              <div style={{flexShrink:0,width:42,height:42,borderRadius:10,overflow:"hidden",background:`${w.color}22`,border:`1px solid ${w.color}55`}}>
                <img src={SPRITES.alien} alt="alien" style={{width:"100%",height:"100%",objectFit:"contain"}}/>
              </div>
              <div style={{background:`${w.color}22`,border:`1px solid ${w.color}55`,borderRadius:"12px 12px 12px 4px",padding:"8px 12px",fontSize:12,color:WHITE,lineHeight:1.5}}>
                Escolha a alternativa correta! ⬇️
              </div>
            </div>
            {q.alternativas.map((opt,i)=>(
              <div key={i} onClick={()=>handleAnswer(i)} style={{
                background:CARD2, border:`1.5px solid #ffffff18`,
                borderRadius:12, padding:"10px 14px", marginBottom:8, cursor:"pointer",
                display:"flex", alignItems:"center", gap:10, fontSize:13, color:WHITE,
                transition:"all 0.15s",
              }}>
                <span style={{width:24,height:24,borderRadius:"50%",background:`${PURPLE}33`,border:`1.5px solid ${PURPLE}`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:11,fontWeight:700,flexShrink:0}}>
                  {String.fromCharCode(65+i)}
                </span>
                {opt}
              </div>
            ))}
          </div>
        )}

        {/* === PHASE: FEEDBACK === */}
        {phase==="feedback" && (
          <div>
            {/* Result banner */}
            <div style={{
              background: isCorrect ? "#14532d" : "#450a0a",
              border: `2px solid ${isCorrect?"#4ade80":"#f87171"}`,
              borderRadius:16, padding:"14px 16px", marginBottom:14, textAlign:"center",
            }}>
              <div style={{fontSize:28, marginBottom:4}}>{isCorrect?"🎉":"😅"}</div>
              <div style={{fontSize:16, fontWeight:900, color:isCorrect?"#4ade80":"#f87171"}}>
                {isCorrect?"Correto! Arrasou!" :"Quase! Não desanime!"}
              </div>
              {!isCorrect && (
                <div style={{fontSize:12,color:"#fca5a5",marginTop:4}}>
                  Resposta certa: <strong>{q.alternativas[q.correta]}</strong>
                </div>
              )}
            </div>
            {/* Reinforcement card */}
            <div style={{background:CARD2,borderRadius:16,padding:"13px 15px",border:`1px solid ${w.color}44`,marginBottom:14}}>
              <div style={{display:"flex",gap:10,alignItems:"flex-start",marginBottom:8}}>
                <div style={{flexShrink:0,width:36,height:36,borderRadius:8,overflow:"hidden",background:`${w.color}22`}}>
                  <img src={SPRITES.alien} alt="alien" style={{width:"100%",height:"100%",objectFit:"contain"}}/>
                </div>
                <div style={{fontSize:12,color:WHITE,lineHeight:1.55}}>
                  <strong style={{color:w.accent}}>{q.slang}</strong> = {q.significado}
                </div>
              </div>
              <div style={{background:`${w.color}18`,borderRadius:10,padding:"8px 11px",fontSize:12,color:"#e0d4ff",fontStyle:"italic",lineHeight:1.5}}>
                {q.exemplo}
              </div>
            </div>
            {/* Answer review */}
            <div style={{marginBottom:14}}>
              {q.alternativas.map((opt,i)=>(
                <div key={i} style={{
                  background:i===q.correta?"#14532d":chosen===i?"#450a0a":CARD2,
                  border:`1.5px solid ${i===q.correta?"#4ade80":chosen===i?"#f87171":"#ffffff18"}`,
                  borderRadius:12, padding:"9px 14px", marginBottom:7,
                  display:"flex", alignItems:"center", gap:10, fontSize:12, color:WHITE,
                }}>
                  <span style={{fontSize:14,flexShrink:0}}>
                    {i===q.correta?"✅":chosen===i?"❌":"  "}
                  </span>
                  {opt}
                </div>
              ))}
            </div>
            <Btn onClick={handleNext} color={w.color} style={{width:"100%"}}>
              {step+1>=quiz.length?"Ver Resumo 🏁":"Próxima Gíria →"}
            </Btn>
          </div>
        )}
      </div>
    </div>
  );
}

