// SCREEN 7 — CERTIFICADO
// ══════════════════════════════════════════
function Screen07_Certificate({go}) {
  const w = WORLDS[0];
  return (
    <div style={{position:"relative",minHeight:"100%",background:`radial-gradient(ellipse at 50% 20%, ${w.sky1} 0%, ${BG} 70%)`,display:"flex",flexDirection:"column",alignItems:"center",padding:"22px 18px 28px",textAlign:"center"}}>
      <StarField count={35} seed={9}/>
      <div style={{position:"relative",zIndex:1,width:"100%"}}>
        <div style={{fontSize:46,marginBottom:4}}>🎉</div>
        <div style={{fontSize:22,fontWeight:900,color:WHITE}}>Parabéns, Astronauta!</div>
        <div style={{fontSize:13,color:PURPLE_LIGHT,marginTop:3}}>Você conquistou o {w.name}!</div>
        {/* Certificate */}
        <div style={{background:`linear-gradient(135deg,${w.color}33,${PURPLE}22)`,border:`2px solid ${w.color}`,borderRadius:20,padding:"16px",margin:"14px 0"}}>
          <div style={{fontSize:10,color:w.color,fontWeight:700,letterSpacing:2,marginBottom:8}}>CERTIFICADO DE CONCLUSÃO</div>
          <div style={{width:70,height:70,borderRadius:"50%",margin:"0 auto 8px",overflow:"hidden",background:`${w.color}33`,border:`2px solid ${w.color}`}}>
            <img src={SPRITES[w.sprite]} alt={w.name} style={{width:"100%",height:"100%",objectFit:"cover"}}/>
          </div>
          <div style={{fontSize:16,fontWeight:900,color:WHITE,margin:"4px 0 2px"}}>{w.name}</div>
          <div style={{fontSize:11,color:"#c4b5fd"}}>SMURF · MVP · CLUTCH · FEED · NOOB</div>
          <div style={{display:"flex",justifyContent:"center",gap:5,marginTop:8}}>
            {[...Array(5)].map((_,i)=><span key={i} style={{fontSize:17,color:STAR_Y}}>★</span>)}
          </div>
        </div>
        {/* Unlocked items */}
        <div style={{fontSize:13,color:WHITE,fontWeight:700,marginBottom:10}}>🎁 Itens desbloqueados:</div>
        <div style={{display:"flex",justifyContent:"center",gap:10,marginBottom:16}}>
          {["🎮","🎧","⚔️"].map((em,i)=>(
            <div key={i} style={{background:`${w.color}22`,border:`1.5px solid ${w.color}`,borderRadius:12,padding:"10px 12px",fontSize:12,color:WHITE,textAlign:"center",fontWeight:600}}>
              <div style={{fontSize:22}}>{em}</div>
              <div style={{marginTop:3,fontSize:10}}>{w.items?.[i]||""}</div>
            </div>
          ))}
        </div>
        <div style={{display:"flex",gap:10}}>
          <Btn onClick={()=>go("map")} color={PURPLE} outlined style={{flex:1}}>Mapa</Btn>
          <Btn onClick={()=>go("profile")} color={w.color} style={{flex:1}}>Perfil ✨</Btn>
        </div>
      </div>
    </div>
  );
}

