// ─── Main shell ───
const SCREENS = [
  {id:"splash",      label:"1·Splash",    comp:Screen01_Splash},
  {id:"mode_pai",    label:"2·Modo",      comp:Screen02_Mode},
  {id:"map",         label:"3·Mapa",      comp:Screen03_Map},
  {id:"world_intro", label:"4·Mundo",     comp:Screen04_WorldIntro},
  {id:"lesson",      label:"5·Lição",     comp:Screen05_Lesson},
  {id:"review",      label:"6·Revisão",   comp:Screen06_Review},
  {id:"certificate", label:"7·Certific.", comp:Screen07_Certificate},
  {id:"profile",     label:"8·Perfil",    comp:Screen08_Profile},
];

export default function SlanGOFlow() {
  const [current,setCurrent] = useState("splash");
  const idx = SCREENS.findIndex(s=>s.id===current);
  const Comp = SCREENS[idx].comp;
  return (
    <div style={{fontFamily:"'Segoe UI',system-ui,sans-serif",background:"#06041a",minHeight:"100vh",display:"flex",flexDirection:"column",alignItems:"center",padding:"18px 10px 36px"}}>
      <div style={{width:"100%",maxWidth:720,marginBottom:14,textAlign:"center"}}>
        <div style={{fontSize:24,fontWeight:900,color:"white",letterSpacing:-1}}>
          Slan<span style={{color:TEAL_LIGHT}}>GO</span>
          <span style={{fontSize:11,fontWeight:400,color:"#6B5CA5",marginLeft:10}}>· Fluxo de Telas</span>
        </div>
      </div>
      <div style={{display:"flex",flexWrap:"wrap",justifyContent:"center",gap:5,marginBottom:18,maxWidth:720}}>
        {SCREENS.map(s=>(
          <button key={s.id} onClick={()=>setCurrent(s.id)} style={{
            background:current===s.id?`linear-gradient(135deg,${PURPLE},${TEAL})`:CARD2,
            border:`1.5px solid ${current===s.id?TEAL_LIGHT:"#333"}`,
            borderRadius:99,color:current===s.id?"white":"#a78bfa",
            fontSize:11,fontWeight:700,padding:"5px 12px",cursor:"pointer",fontFamily:"inherit",
            boxShadow:current===s.id?`0 2px 12px ${PURPLE}55`:"none",
          }}>{s.label}</button>
        ))}
      </div>
      <div style={{display:"flex",gap:16,alignItems:"flex-start",justifyContent:"center",flexWrap:"wrap",width:"100%",maxWidth:1200}}>
        {/* Big active */}
        <div style={{display:"flex",flexDirection:"column",alignItems:"center"}}>
          <div style={{fontSize:9,color:"#6B5CA5",marginBottom:5,fontWeight:700,letterSpacing:1}}>TELA ATIVA</div>
          <div style={{width:320,minHeight:620,background:BG,borderRadius:44,overflow:"hidden",position:"relative",border:`2px solid ${TEAL}55`,boxShadow:`0 0 60px ${PURPLE}44,0 0 20px ${TEAL}22`}}>
            <Comp go={id=>setCurrent(id)}/>
          </div>
          <div style={{display:"flex",gap:10,marginTop:10}}>
            <button onClick={()=>setCurrent(SCREENS[Math.max(0,idx-1)].id)} disabled={idx===0} style={{background:CARD,border:`1px solid ${PURPLE}55`,borderRadius:99,color:"#a78bfa",padding:"5px 14px",fontSize:12,fontWeight:700,cursor:idx===0?"not-allowed":"pointer",opacity:idx===0?0.3:1,fontFamily:"inherit"}}>← Anterior</button>
            <button onClick={()=>setCurrent(SCREENS[Math.min(SCREENS.length-1,idx+1)].id)} disabled={idx===SCREENS.length-1} style={{background:CARD,border:`1px solid ${TEAL}55`,borderRadius:99,color:"#5eead4",padding:"5px 14px",fontSize:12,fontWeight:700,cursor:idx===SCREENS.length-1?"not-allowed":"pointer",opacity:idx===SCREENS.length-1?0.3:1,fontFamily:"inherit"}}>Próxima →</button>
          </div>
        </div>
        {/* Thumbnails */}
        <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:7}}>
          <div style={{fontSize:9,color:"#6B5CA5",fontWeight:700,letterSpacing:1}}>TODAS AS TELAS</div>
          <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:7}}>
            {SCREENS.map(s=>{
              const TC=s.comp;
              return (
                <div key={s.id} onClick={()=>setCurrent(s.id)} style={{cursor:"pointer"}}>
                  <div style={{fontSize:8,color:current===s.id?TEAL_LIGHT:"#6B5CA5",fontWeight:700,textAlign:"center",marginBottom:2}}>{s.label}</div>
                  <div style={{width:126,height:212,background:BG,borderRadius:13,overflow:"hidden",position:"relative",pointerEvents:"none",border:`1.5px solid ${current===s.id?TEAL_LIGHT:"#2a1f5c"}`,boxShadow:current===s.id?`0 0 10px ${TEAL}55`:"none"}}>
                    <div style={{transform:"scale(0.394)",transformOrigin:"top left"}}>
                      <div style={{width:320,height:538}}><TC go={()=>{}}/></div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}
